/* ===== LEARNFORGE DESIGN SYSTEM ===== */

/* --- Google Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Inter:wght@400;500;600&display=swap');

/* --- OKLCH Color Palette --- */
:root {
  --color-black: oklch(0% 0 0);
  --color-lime: oklch(94% 0.21 115);
  --color-burgundy: oklch(32% 0.12 25);

  --color-white: oklch(100% 0 0);
  --color-gray-50: oklch(97% 0.005 260);
  --color-gray-100: oklch(95% 0.008 260);
  --color-gray-200: oklch(90% 0.01 260);
  --color-gray-300: oklch(80% 0.01 260);
  --color-gray-500: oklch(55% 0.015 260);
  --color-gray-700: oklch(35% 0.015 260);
  --color-gray-900: oklch(15% 0.02 260);

  --bg-primary: var(--color-white);
  --bg-secondary: var(--color-gray-50);
  --bg-dark: var(--color-black);
  --bg-lime: var(--color-lime);

  --text-primary: var(--color-gray-900);
  --text-secondary: var(--color-gray-700);
  --text-muted: var(--color-gray-500);
  --text-on-dark: var(--color-white);
  --text-on-lime: var(--color-black);

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 32px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px rgba(0,0,0,0.07);
  --shadow-lg: 0 10px 25px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.12);

  --font-heading: 'Plus Jakarta Sans', sans-serif;
  --font-body: 'Inter', sans-serif;

  --container-max: 1200px;
  --container-wide: 1400px;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--bg-primary);
}

img { max-width: 100%; height: auto; display: block; }
a { text-decoration: none; color: inherit; }
ul, ol { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(2rem, 4vw, 3rem); }
h3 { font-size: clamp(1.5rem, 3vw, 2rem); }
h4 { font-size: clamp(1.125rem, 2vw, 1.5rem); }

p { line-height: 1.7; color: var(--text-secondary); }

/* --- Container --- */
.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 24px;
}
.container-wide {
  max-width: var(--container-wide);
  margin: 0 auto;
  padding: 0 24px;
}

/* --- Section Spacing --- */
.section { padding: 96px 0; }
.section-sm { padding: 64px 0; }
.section-lg { padding: 128px 0; }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  padding: 14px 32px;
  border-radius: var(--radius-full);
  transition: all 0.25s ease;
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-black);
  color: var(--color-white);
}
.btn-primary:hover {
  background: var(--color-gray-900);
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-lime {
  background: var(--color-lime);
  color: var(--color-black);
}
.btn-lime:hover {
  filter: brightness(1.05);
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-outline {
  background: transparent;
  color: var(--color-black);
  border: 2px solid var(--color-black);
}
.btn-outline:hover {
  background: var(--color-black);
  color: var(--color-white);
}

.btn-outline-light {
  background: transparent;
  color: var(--color-white);
  border: 2px solid rgba(255,255,255,0.3);
}
.btn-outline-light:hover {
  background: var(--color-white);
  color: var(--color-black);
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--color-gray-200);
  transition: box-shadow 0.3s ease;
}
.nav.scrolled { box-shadow: var(--shadow-md); }

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: var(--container-wide);
  margin: 0 auto;
  padding: 0 24px;
  height: 72px;
}

.nav-logo {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 1.5rem;
  color: var(--color-black);
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-logo span { color: var(--color-lime); background: var(--color-black); padding: 2px 6px; border-radius: 4px; font-size: 0.85em; }

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}
.nav-links a {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--text-secondary);
  transition: color 0.2s;
  position: relative;
}
.nav-links a:hover { color: var(--color-black); }
.nav-links a.active { color: var(--color-black); }
.nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-lime);
  border-radius: 1px;
}

.nav-cta { margin-left: 8px; }

.nav-mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}
.nav-mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-black);
  border-radius: 1px;
  transition: all 0.3s ease;
}

/* --- Hero --- */
.hero {
  padding: 140px 0 80px;
  background: var(--color-black);
  color: var(--color-white);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(230,255,50,0.08) 0%, transparent 70%);
  border-radius: 50%;
}
.hero::after {
  content: '';
  position: absolute;
  bottom: -30%;
  left: -10%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(127,42,35,0.12) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-content {
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.hero h1 { margin-bottom: 24px; }
.hero p { font-size: 1.2rem; color: var(--color-gray-300); margin-bottom: 40px; max-width: 640px; margin-left: auto; margin-right: auto; }

.hero-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

.hero-tabs {
  display: flex;
  justify-content: center;
  gap: 4px;
  margin-top: 48px;
  background: rgba(255,255,255,0.08);
  border-radius: var(--radius-full);
  padding: 4px;
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
}
.hero-tab {
  padding: 10px 24px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--color-gray-300);
  transition: all 0.3s ease;
}
.hero-tab.active {
  background: var(--color-lime);
  color: var(--color-black);
}

.hero-preview {
  margin-top: 32px;
  background: var(--color-gray-900);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid rgba(255,255,255,0.08);
  min-height: 280px;
  position: relative;
  text-align: left;
}

.hero-preview-panel { display: none; }
.hero-preview-panel.active { display: block; }

.preview-mockup {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 24px;
  min-height: 220px;
}
.preview-sidebar {
  background: rgba(255,255,255,0.04);
  border-radius: var(--radius-md);
  padding: 16px;
}
.preview-sidebar-item {
  padding: 8px 12px;
  margin-bottom: 4px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  color: var(--color-gray-300);
}
.preview-sidebar-item.active {
  background: var(--color-lime);
  color: var(--color-black);
  font-weight: 600;
}
.preview-main {
  background: rgba(255,255,255,0.04);
  border-radius: var(--radius-md);
  padding: 20px;
}
.preview-main h4 { font-size: 1rem; margin-bottom: 8px; }
.preview-main p { font-size: 0.8rem; color: var(--color-gray-300); }

.preview-student-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.student-card {
  background: rgba(255,255,255,0.04);
  border-radius: var(--radius-md);
  padding: 20px;
  text-align: center;
}
.student-card h4 { font-size: 0.9rem; margin-bottom: 6px; }
.student-card p { font-size: 0.75rem; }
.student-progress {
  margin-top: 8px;
  height: 4px;
  background: rgba(255,255,255,0.1);
  border-radius: 2px;
  overflow: hidden;
}
.student-progress-fill {
  height: 100%;
  background: var(--color-lime);
  border-radius: 2px;
}

/* --- Stats Bar --- */
.stats-bar {
  background: var(--color-lime);
  padding: 48px 0;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}
.stat-item h3 {
  font-size: clamp(2.5rem, 5vw, 3.5rem);
  color: var(--color-black);
}
.stat-item p {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1rem;
  color: var(--color-gray-700);
  margin-top: 4px;
}

/* --- Products Grid --- */
.products { background: var(--bg-secondary); }
.products-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 48px;
}
.product-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 40px;
  border: 1px solid var(--color-gray-200);
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}
.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
  border-color: var(--color-lime);
}
.product-card-icon {
  width: 56px;
  height: 56px;
  background: var(--color-lime);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}
.product-card h3 { margin-bottom: 12px; }
.product-card p { margin-bottom: 20px; }
.product-card-link {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--color-black);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: gap 0.2s ease;
}
.product-card:hover .product-card-link { gap: 10px; }

/* --- Section Headers --- */
.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto;
}
.section-header h2 { margin-bottom: 16px; }
.section-header p { font-size: 1.1rem; }
.section-label {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-lime);
  background: var(--color-black);
  display: inline-block;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  margin-bottom: 16px;
}
.section-label-on-light {
  color: var(--color-black);
  background: var(--color-lime);
}

/* --- Why Choose Us (Tabs) --- */
.why-choose { background: var(--bg-secondary); }

.why-tabs {
  display: flex;
  justify-content: center;
  gap: 4px;
  margin-top: 48px;
  margin-bottom: 40px;
  background: var(--color-white);
  border-radius: var(--radius-full);
  padding: 4px;
  border: 1px solid var(--color-gray-200);
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
  flex-wrap: wrap;
}
.why-tab {
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.85rem;
  color: var(--text-muted);
  transition: all 0.3s ease;
}
.why-tab.active {
  background: var(--color-black);
  color: var(--color-white);
}
.why-tab:hover:not(.active) { color: var(--text-primary); }

.why-panel { display: none; }
.why-panel.active { display: block; }

.why-features {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 20px;
}
.why-feature-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  background: var(--color-white);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-gray-200);
}
.why-feature-icon {
  width: 32px;
  height: 32px;
  min-width: 32px;
  background: var(--color-lime);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9rem;
}
.why-feature-item h4 { font-size: 0.95rem; margin-bottom: 2px; }
.why-feature-item p { font-size: 0.85rem; color: var(--text-muted); }

/* --- Global Scale --- */
.global-scale {
  background: var(--color-black);
  color: var(--color-white);
  position: relative;
  overflow: hidden;
}
.global-scale::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(230,255,50,0.06) 0%, transparent 70%);
  border-radius: 50%;
}
.global-content {
  position: relative;
  z-index: 1;
  text-align: center;
}
.global-content h2 { margin-bottom: 16px; }
.global-content p { color: var(--color-gray-300); font-size: 1.1rem; max-width: 560px; margin: 0 auto 40px; }
.global-features {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  max-width: 900px;
  margin: 0 auto;
}
.global-feature {
  background: rgba(255,255,255,0.05);
  border-radius: var(--radius-md);
  padding: 24px;
  border: 1px solid rgba(255,255,255,0.08);
}
.global-feature h4 { font-size: 1rem; margin-bottom: 8px; }
.global-feature p { font-size: 0.85rem; color: var(--color-gray-300); }

/* --- AI Automations --- */
.ai-section { background: var(--bg-primary); }
.ai-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-top: 48px;
}
.ai-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 18px;
  background: var(--bg-secondary);
  border-radius: var(--radius-md);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.9rem;
  border: 1px solid var(--color-gray-200);
  transition: all 0.2s ease;
}
.ai-item:hover {
  border-color: var(--color-lime);
  background: var(--color-white);
}
.ai-icon {
  width: 28px;
  height: 28px;
  min-width: 28px;
  background: var(--color-lime);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
}

/* --- Testimonials Carousel --- */
.testimonials { background: var(--bg-secondary); }
.testimonials-track {
  position: relative;
  margin-top: 48px;
  overflow: hidden;
}
.testimonials-slider {
  display: flex;
  transition: transform 0.5s ease;
}
.testimonial-card {
  min-width: 100%;
  padding: 0 8px;
}
.testimonial-inner {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 48px;
  border: 1px solid var(--color-gray-200);
  max-width: 700px;
  margin: 0 auto;
}
.testimonial-quote {
  font-size: 1.15rem;
  line-height: 1.7;
  color: var(--text-primary);
  margin-bottom: 24px;
  font-style: italic;
}
.testimonial-quote::before { content: '\201C'; font-size: 3rem; color: var(--color-lime); font-family: serif; line-height: 0; vertical-align: -0.3em; margin-right: 4px; }
.testimonial-author { display: flex; align-items: center; gap: 16px; }
.testimonial-avatar {
  width: 48px;
  height: 48px;
  background: var(--color-lime);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 1.1rem;
  color: var(--color-black);
}
.testimonial-info h4 { font-size: 1rem; }
.testimonial-info p { font-size: 0.85rem; color: var(--text-muted); }
.testimonial-tag {
  display: inline-block;
  background: var(--color-lime);
  padding: 2px 10px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 32px;
}
.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  border: 2px solid var(--color-gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  color: var(--text-secondary);
  transition: all 0.2s ease;
  background: var(--color-white);
}
.carousel-btn:hover {
  border-color: var(--color-black);
  background: var(--color-black);
  color: var(--color-white);
}
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 20px;
}
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-full);
  background: var(--color-gray-300);
  transition: all 0.3s ease;
  border: none;
  cursor: pointer;
}
.carousel-dot.active {
  background: var(--color-black);
  width: 24px;
}

/* --- Pricing Overview --- */
.pricing { background: var(--bg-primary); }
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}
.pricing-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 36px;
  border: 2px solid var(--color-gray-200);
  transition: all 0.3s ease;
  position: relative;
}
.pricing-card.featured {
  border-color: var(--color-lime);
  box-shadow: var(--shadow-lg);
}
.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-lime);
  color: var(--color-black);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.75rem;
  padding: 4px 16px;
  border-radius: var(--radius-full);
}
.pricing-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}
.pricing-name {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.1rem;
  margin-bottom: 8px;
}
.pricing-price {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 2.5rem;
  margin-bottom: 4px;
}
.pricing-price span { font-size: 1rem; font-weight: 500; color: var(--text-muted); }
.pricing-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 24px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--color-gray-200);
}
.pricing-features { margin-bottom: 28px; }
.pricing-features li {
  padding: 6px 0;
  font-size: 0.9rem;
  color: var(--text-secondary);
  display: flex;
  align-items: flex-start;
  gap: 8px;
}
.pricing-features li::before {
  content: '✓';
  color: var(--color-black);
  font-weight: 700;
  min-width: 16px;
}
.pricing-card .btn { width: 100%; }

/* --- Integrations --- */
.integrations { background: var(--bg-secondary); }
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 16px;
  margin-top: 48px;
}
.integration-item {
  background: var(--color-white);
  border-radius: var(--radius-md);
  padding: 20px;
  text-align: center;
  border: 1px solid var(--color-gray-200);
  transition: all 0.2s ease;
}
.integration-item:hover {
  border-color: var(--color-lime);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.integration-logo {
  width: 40px;
  height: 40px;
  margin: 0 auto 10px;
  background: var(--color-gray-100);
