}
.resource-icon {
  width: 40px;
  height: 40px;
  min-width: 40px;
  background: var(--color-lime);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
}
.resource-card h4 { font-size: 1rem; margin-bottom: 4px; }
.resource-card p { font-size: 0.85rem; }

/* --- File Types --- */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 16px;
  margin-top: 48px;
}
.file-type-item {
  background: var(--bg-secondary);
  border-radius: var(--radius-md);
  padding: 24px 16px;
  text-align: center;
  border: 1px solid var(--color-gray-200);
  transition: all 0.2s ease;
}
.file-type-item:hover {
  border-color: var(--color-lime);
  background: var(--color-white);
}
.file-type-icon {
  font-size: 2rem;
  margin-bottom: 8px;
}
.file-type-item p {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.85rem;
}

/* --- Membership Pricing --- */
.membership-pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 24px;
  margin-top: 48px;
}
.membership-tier {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 36px;
  border: 1px solid var(--color-gray-200);
  text-align: center;
  transition: all 0.3s ease;
}
.membership-tier:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-lime);
}
.membership-tier h4 { margin-bottom: 8px; }
.membership-tier p { font-size: 0.9rem; }

/* --- Value Props --- */
.value-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}
.value-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 36px;
  border: 1px solid var(--color-gray-200);
  transition: all 0.3s ease;
}
.value-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-lime);
}
.value-card h3 { font-size: 1.2rem; margin-bottom: 8px; }
.value-card p { font-size: 0.9rem; }

/* --- Business Fit --- */
.business-fit-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 48px;
}
.business-fit-card {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  padding: 36px;
  border: 1px solid var(--color-gray-200);
}
.business-fit-card h4 { margin-bottom: 8px; }
.business-fit-card p { font-size: 0.9rem; }

/* --- Mobile Responsive --- */
@media (max-width: 1024px) {
  .pricing-grid { grid-template-columns: 1fr; max-width: 420px; margin-left: auto; margin-right: auto; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .global-features { grid-template-columns: 1fr; max-width: 400px; margin: 0 auto; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    background: var(--color-white);
    padding: 24px;
    border-bottom: 1px solid var(--color-gray-200);
    gap: 16px;
    box-shadow: var(--shadow-lg);
  }
  .nav-mobile-toggle { display: flex; }
  .nav-cta { margin-left: 0; }

  .products-grid { grid-template-columns: 1fr; }
  .features-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; }
  .steps-grid::before { display: none; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .value-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr; gap: 24px; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .why-tabs { flex-direction: column; width: 100%; }
  .why-tab { text-align: center; }
  .business-fit-grid { grid-template-columns: 1fr; }

  .hero { padding: 120px 0 60px; }
  .hero-actions { flex-direction: column; align-items: center; }
  .preview-mockup { grid-template-columns: 1fr; }
  .preview-student-grid { grid-template-columns: 1fr; }

  .section { padding: 64px 0; }
  .section-lg { padding: 80px 0; }

  .cta-banner .btn { margin-bottom: 12px; }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .testimonial-inner { padding: 28px; }
  .ai-grid { grid-template-columns: 1fr 1fr; }
  .integrations-grid { grid-template-columns: repeat(3, 1fr); }
  .tools-grid { grid-template-columns: repeat(2, 1fr); }
}

/* --- Animations --- */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-in {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.animate-in.visible {
  opacity: 1;
  transform: translateY(0);
}
